class ProbeBadge extends HTMLElement {
  static observedAttributes = ["label", "count", "disabled"];

  constructor() {
    super();
    this.attachShadow({ mode: "open" }).innerHTML =
      '<button type="button"></button><slot></slot>';
    this.button = this.shadowRoot.querySelector("button");
  }

  connectedCallback() {
    this.button.addEventListener("click", this);
    this.render();
  }

  disconnectedCallback() {
    this.button.removeEventListener("click", this);
  }

  attributeChangedCallback() {
    this.render();
  }

  handleEvent() {
    this.dispatchEvent(
      new CustomEvent("count-change", {
        detail: Number(this.getAttribute("count") || 0) + 1,
        bubbles: true,
      }),
    );
  }

  render() {
    this.button.textContent = `${this.getAttribute("label") || "Likes"}: ${Number(this.getAttribute("count") || 0)}`;
    this.button.disabled = this.hasAttribute("disabled");
  }
}

customElements.define("probe-badge", ProbeBadge);
